    terms: ['neuroleptic malignant syndrome', 'serotonin syndrome', 'malignant hyperthermia', 'clonus', 'lead pipe rigidity', 'dantrolene', 'cyproheptadine', 'bromocriptine', 'procyclidine', 'benztropine', 'dystonia', 'oculogyric crisis', 'akathisia', 'tardive dyskinesia', 'antipsychotic', 'ssri', 'maoi', 'suxamethonium', 'volatile anaesthetic', 'rhabdomyolysis'],
